class EquipmentPayload(V2PayloadBase):
    setup_ref: NonBlankStr
    setup_origin: Literal['commercial', 'lab_built', 'modified']
    manufacturer_brand: str | None = None
    model: str | None = None
    design_build_organization: str | None = None
    internal_model: str | None = None
    modification_details: str | None = None
    wall_type: Literal['cold_wall', 'hot_wall'] | None = None
    zone_count: Annotated[int, Field(strict=True, ge=1)]
    orientation: Literal['horizontal', 'vertical']
    tube_material_shape: TubeMaterialShapePayload | None = None
    tube_outer_diameter_wall_mm: TubeDimensionsPayload | None = None
    coordinate_system: str | None = None
    temperature_sensors: Annotated[list[TemperatureSensorPayload], Field(min_length=1)]
    field_devices: list[Literal['electric_field', 'light', 'none', 'other', 'plasma']] | None = None
    field_device_other_name: str | None = None
    setup_diagram: FileAssetReferencePayload | None = None
    tube_usage_history: TubeUsageHistoryPayload

    @model_validator(mode="after")
    def _tube_shape_dimensions(self) -> Self:
        shape = self.tube_material_shape
        dimensions = self.tube_outer_diameter_wall_mm
        if (shape is None) != (dimensions is None):
            raise ValueError("tube material/shape and dimensions must be provided together")
        if shape is None or dimensions is None:
            return self
        expected_fields = {
            'round': {'outer_diameter_mm', 'wall_thickness_mm'},
            'square': {'outer_side_mm', 'wall_thickness_mm'},
            'rectangular': {'outer_width_mm', 'outer_height_mm', 'wall_thickness_mm'},
            'other': {'dimension_description'},
        }[shape.shape]
        provided_fields = {
            key
            for key in (
                'outer_diameter_mm',
                'outer_side_mm',
                'outer_width_mm',
                'outer_height_mm',
                'wall_thickness_mm',
                'dimension_description',
            )
            if getattr(dimensions, key) is not None
        }
        if provided_fields != expected_fields:
            raise ValueError("tube dimensions do not match tube cross-section shape")
        return self

    @model_validator(mode="after")
    def _temperature_sensor_zone_coverage(self) -> Self:
        zone_indices = sorted(sensor.zone_index for sensor in self.temperature_sensors)
        if len(zone_indices) != self.zone_count or any(
            zone_index != expected
            for expected, zone_index in enumerate(zone_indices, start=1)
        ):
            raise ValueError("temperature_sensors must cover each zone exactly once")
        return self

    @model_validator(mode="after")
    def _check_conditional_required(self) -> Self:
        if (
            not _matches({'op': 'in', 'value': ['commercial', 'modified']}, self.setup_origin)
            and not _missing(self.manufacturer_brand)
        ):
            raise ValueError("manufacturer_brand is not applicable")
        if (
            not _matches({'op': 'in', 'value': ['commercial', 'modified']}, self.setup_origin)
            and not _missing(self.model)
        ):
            raise ValueError("model is not applicable")
        if (
            not _matches({'op': 'eq', 'value': 'lab_built'}, self.setup_origin)
            and not _missing(self.design_build_organization)
        ):
            raise ValueError("design_build_organization is not applicable")
        if (
            not _matches({'op': 'eq', 'value': 'lab_built'}, self.setup_origin)
            and not _missing(self.internal_model)
        ):
            raise ValueError("internal_model is not applicable")
        if (
            not _matches({'op': 'eq', 'value': 'modified'}, self.setup_origin)
            and not _missing(self.modification_details)
        ):
            raise ValueError("modification_details is not applicable")
        if (
            _matches({'op': 'eq', 'value': 'other'}, self.field_devices)
            and _missing(self.field_device_other_name)
        ):
            raise ValueError("field_device_other_name is conditionally required")
        if (
            not _matches({'op': 'eq', 'value': 'other'}, self.field_devices)
            and not _missing(self.field_device_other_name)
        ):
            raise ValueError("field_device_other_name is not applicable")
        return self



